 import React, { useState, useEffect, useCallback } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../contexts/ToastContext'
import { Link, useNavigate } from 'react-router-dom'
import { 
  Trophy, 
  Medal, 
  Crown, 
  Users, 
  TrendingUp,
  Calendar,
  Heart,
  CheckCircle,
  Home,
  Plane,
  Minus,
  Sparkles,
  Clock,
  Loader
} from 'lucide-react'
import VerifiedBadge from '../components/VerifiedBadge'
import { checkUserSubscription } from '../services/subscriptionService'
import { getTodaysMatches, formatMatch, COMPETITIONS } from '../services/footballApi'
import { generatePrediction } from '../services/predictionEngine'

export default function Leaderboard() {
    const { user } = useAuth()
    const { showToast } = useToast()
    const navigate = useNavigate()
    const [predictions, setPredictions] = useState([])
    const [leaderboardUsers, setLeaderboardUsers] = useState([])
    const [loading, setLoading] = useState(true)
    const [timeFrame, setTimeFrame] = useState('today')
    const [isSubscribed, setIsSubscribed] = useState(false)
    const [checking, setChecking] = useState(true)

    // ✅ Check Subscription Status
    useEffect(() => {
        const checkAccess = async () => {
            if (!user) {
                navigate('/login')
                return
            }
            
            const subscribed = await checkUserSubscription(user.id)
            setIsSubscribed(subscribed)
            setChecking(false)

            if (!subscribed && window.location.pathname !== '/subscribe') {
                navigate('/subscribe')
            }
        }
        checkAccess()
    }, [user, navigate])

    // ✅ Load Predictions
    const loadPredictions = useCallback(async () => {
        try {
            const leagueIds = Object.values(COMPETITIONS)
            const allPredictions = []

            for (const leagueId of leagueIds) {
                try {
                    const { matches, standingsMap } = await getTodaysMatches(leagueId)
                    const formattedMatches = matches.map(match => formatMatch(match))

                    // Generate prediction for each match
                    const matchesWithPredictions = formattedMatches.map(match => {
                        const homeStats = standingsMap[match.homeTeam?.id]
                        const awayStats = standingsMap[match.awayTeam?.id]
                        
                        const prediction = generatePrediction(
                            match.homeTeam,
                            match.awayTeam,
                            homeStats,
                            awayStats
                        )

                        return { ...match, prediction }
                    })

                    // Take only the first 10 upcoming matches for this league
                    allPredictions.push(...matchesWithPredictions.slice(0, 10))
                } catch (error) {
                    console.error(`Error loading league ${leagueId}:`, error)
                }
            }

            setPredictions(allPredictions)
        } catch (error) {
            console.error('Error loading predictions:', error)
            showToast('Failed to load predictions', 'error')
        }
    }, [showToast])

    // ✅ Load Leaderboard (Top 10 users)
    const loadLeaderboard = useCallback(async () => {
        try {
            const { data, error } = await supabase
                .from('profiles')
                .select('id, username, full_name, avatar_url, points, predictions_count, accuracy, is_verified')
                .order('points', { ascending: false })
                .limit(10)

            if (error) throw error

            setLeaderboardUsers(data || [])
        } catch (error) {
            console.error('Error loading leaderboard:', error)
        }
    }, [])

    // ✅ Load everything when user is subscribed
    useEffect(() => {
        if (isSubscribed) {
            const loadAll = async () => {
                setLoading(true)
                await Promise.all([
                    loadPredictions(),
                    loadLeaderboard()
                ])
                setLoading(false)
            }
            loadAll()
        }
    }, [isSubscribed, loadPredictions, loadLeaderboard])

    // While checking subscription, show loading state
    if (checking) {
        return (
            <div className="min-h-[60vh] flex items-center justify-center">
                <div className="text-center">
                    <Loader className="w-8 h-8 text-gray-400 animate-spin mx-auto" />
                    <div className="text-xl text-gray-500 mt-2">Checking subscription...</div>
                </div>
            </div>
        )
    }

    // If not subscribed and we are NOT on the subscribe page
    if (!isSubscribed) return null

    // ✅ Render Prediction Card
    const renderPredictionCard = (match) => {
        const homeName = match.homeTeam?.name || 'Unknown'
        const awayName = match.awayTeam?.name || 'Unknown'
        const homeCrest = match.homeTeam?.crest
        const awayCrest = match.awayTeam?.crest
        const prediction = match.prediction || {}

        return (
            <div key={match.id} className="bg-white rounded-xl shadow-md p-4 mb-4">
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3 flex-1">
                        <div className="flex items-center gap-2">
                            {homeCrest ? (
                                <img src={homeCrest} alt={homeName} className="w-8 h-8 object-contain" />
                            ) : (
                                <div className="w-8 h-8 bg-gray-200 rounded-full flex items-center justify-center text-xs font-bold text-gray-600">
                                    {homeName.charAt(0)}
                                </div>
                            )}
                            <span className="font-bold text-gray-800 text-sm">{homeName}</span>
                        </div>
                        <span className="text-gray-400 text-xs">vs</span>
                        <div className="flex items-center gap-2">
                            <span className="font-bold text-gray-800 text-sm">{awayName}</span>
                            {awayCrest ? (
                                <img src={awayCrest} alt={awayName} className="w-8 h-8 object-contain" />
                            ) : (
                                <div className="w-8 h-8 bg-gray-200 rounded-full flex items-center justify-center text-xs font-bold text-gray-600">
                                    {awayName.charAt(0)}
                                </div>
                            )}
                        </div>
                    </div>
                    <div className="flex items-center gap-2 text-xs text-gray-400">
                        <Clock size={14} /> 
                        {match.kickoff ? new Date(match.kickoff).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '--:--'}
                    </div>
                </div>

                {/* Prediction Card */}
                <div className="mt-4 bg-gradient-to-r from-green-50 to-blue-50 border border-green-200 rounded-xl p-4">
                    <div className="flex items-center justify-center gap-2 mb-2">
                        <Sparkles size={16} className="text-green-600" />
                        <span className="text-sm font-bold text-gray-800">AI Predicted Tips</span>
                    </div>
                    <div className="grid grid-cols-3 gap-2 text-center">
                        <div className="bg-white rounded-lg p-2 border border-green-200">
                            <div className="text-xs text-gray-500">Match Result</div>
                            <div className="font-bold text-green-700 text-sm mt-1">{prediction.matchResult || 'Draw'}</div>
                        </div>
                        <div className="bg-white rounded-lg p-2 border border-green-200">
                            <div className="text-xs text-gray-500">Over/Under</div>
                            <div className="font-bold text-green-700 text-sm mt-1">{prediction.overUnder || 'Over 2.5'}</div>
                        </div>
                        <div className="bg-white rounded-lg p-2 border border-green-200">
                            <div className="text-xs text-gray-500">BTTS</div>
                            <div className="font-bold text-green-700 text-sm mt-1">{prediction.btts || 'No'}</div>
                        </div>
                    </div>
                    <div className="mt-3 text-center">
                        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                            prediction.confidence === 'High' 
                                ? 'bg-green-500 text-white' 
                                : prediction.confidence === 'Medium' 
                                    ? 'bg-yellow-500 text-white' 
                                    : 'bg-gray-400 text-white'
                        }`}>
                            {prediction.confidence || 'Low'} Confidence
                        </span>
                    </div>
                </div>
            </div>
        )
    }

    return (
        <div>
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-6 gap-4">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800 flex items-center gap-2">
                        <Sparkles size={24} className="text-green-600" /> Premium Predictions & Leaderboard
                    </h1>
                    <p className="text-gray-500">AI-powered predictions + Top predictors</p>
                </div>
                
                <div className="flex gap-2">
                    <button
                        onClick={() => setTimeFrame('today')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-1 ${
                            timeFrame === 'today' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        <TrendingUp size={16} /> Today
                    </button>
                    <button
                        onClick={() => setTimeFrame('week')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            timeFrame === 'week' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        This Week
                    </button>
                    <button
                        onClick={() => setTimeFrame('month')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            timeFrame === 'month' 
                                ? 'bg-green-600 text-white' 
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        This Month
                    </button>
                </div>
            </div>

            {/* ✅ AI PREDICTIONS SECTION */}
            <div className="mb-8">
                <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <Sparkles size={20} className="text-green-600" /> Today's AI Predictions
                </h2>
                
                {loading ? (
                    <div className="text-center py-12">
                        <Loader className="w-8 h-8 text-gray-400 animate-spin mx-auto" />
                        <div className="text-gray-400 mt-2">Loading predictions...</div>
                    </div>
                ) : predictions.length === 0 ? (
                    <div className="text-center py-12 bg-white rounded-xl shadow-md">
                        <Sparkles className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                        <p className="text-gray-500">No predictions available</p>
                        <p className="text-sm text-gray-400">We'll show you the best AI tips as soon as matches are available</p>
                    </div>
                ) : (
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {predictions.map(renderPredictionCard)}
                    </div>
                )}
            </div>

            {/* ✅ LEADERBOARD SECTION */}
            <div className="mb-8">
                <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <Trophy size={20} className="text-yellow-500" /> Top Predictors
                </h2>

                {leaderboardUsers.length === 0 ? (
                    <div className="text-center py-12 bg-white rounded-xl shadow-md">
                        <Trophy className="w-16 h-16 text-gray-300 mx-auto mb-4" />
                        <p className="text-gray-500">No predictors yet</p>
                        <p className="text-sm text-gray-400">Be the first to share a prediction and climb the leaderboard!</p>
                    </div>
                ) : (
                    <div className="space-y-4">
                        {leaderboardUsers.map((profile, index) => {
                            const isOwn = user?.id === profile.id
                            const medal = index === 0 ? '🥇' : index === 1 ? '🥈' : index === 2 ? '🥉' : `${index + 1}.`

                            return (
                                <div 
                                    key={profile.id} 
                                    className={`bg-white rounded-xl shadow-md p-4 flex items-center gap-4 ${
                                        isOwn ? 'border-2 border-green-500' : ''
                                    }`}
                                >
                                    <div className="w-12 h-12 flex items-center justify-center text-2xl font-bold">
                                        {medal}
                                    </div>
                                    <div className="flex-1">
                                        <div className="font-semibold flex items-center gap-1.5">
                                            {profile.full_name || profile.username || 'Unknown'}
                                            {profile.is_verified && <VerifiedBadge size="sm" />}
                                            {isOwn && <span className="text-xs bg-green-100 text-green-700 px-2 py-0.5 rounded-full">You</span>}
                                        </div>
                                        <div className="text-sm text-gray-500">@{profile.username || 'user'}</div>
                                    </div>
                                    <div className="text-right">
                                        <div className="font-bold text-gray-800">{profile.points || 0} pts</div>
                                        <div className="text-xs text-gray-400">{profile.predictions_count || 0} predictions</div>
                                    </div>
                                </div>
                            )
                        })}
                    </div>
                )}
            </div>
        </div>
    )
}
